_mappingScript.incomingScript:
function mapToDittoProtocol(headers, textPayload, bytePayload, contentType) {
  const p = JSON.parse(textPayload);
  return {
    thingId: 'ics:water-tank-TK-001',
    policyId: 'ics:water-tank-policy',
    topic: 'ics/water-tank-TK-001/things/twin/commands/modify',
    path: '/features',
    value: {
      sensors: { properties: { status: { tankLevel: p.level, pressure_bar: p.pressure, temperature_C: p.temperature } } },
      actuators: { properties: { status: { fillPump: p.fillPump, drainValve: p.drainValve } } },
      alarms: { properties: { status: { alarmLowLevel: p.alarmLow, alarmHighLevel: p.alarmHigh } } },
      setpoints: { properties: { desired: { setpoint: p.setpoint, mode: p.mode } } }
    }
  };
}

_mappingScript.outgoingScript:
function mapFromDittoProtocol(namespace, id, channel, criterion, action, path, dittoHeaders, value) {
  if (path.startsWith('/features/setpoints/properties/desired')) {
    return { topic: 'tank/commands/setpoint', textPayload: String(value.setpoint || 60) };
  }
  if (path.startsWith('/features/actuators')) {
    if (value.mode === 'auto') return { topic: 'tank/commands/auto_mode', textPayload: 'true' };
    return { topic: 'tank/commands/auto_mode', textPayload: 'false' };
  }
  return null;
}
